1	/**
2	 * Membership and role changes, including the invariant that an organization always keeps one owner.
3	 *
4	 * Must call (do not reimplement): assertCan, assertOrgScope, emit, hasRoleAtLeast
5	 */
6	import { emit } from "@/lib/event-bus";
7	import { assertCan } from "@/lib/permissions";
8	import { assertOrgScope } from "@/lib/tenant";
9	import * as memberRepo from "@/server/repositories/member-repository";
10	import { hasRoleAtLeast } from "@/types/member";
11	import { actorEnvelope, memberResource, requireFound } from "./_support";
12	import type {
13	  ListMembersInput,
14	  RemoveMemberInput,
15	  UpdateMemberRoleInput,
16	} from "@/schemas/member";
17	import type { MemberId, OrgId, Page, UserId } from "@/types/common";
18	import type { Actor, Member, MemberWithUser, Role } from "@/types/member";
19	
20	/** How many members are scanned when counting the remaining owners. */
21	const OWNER_SCAN_LIMIT = 100;
22	
23	export async function listMembers(
24	  actor: Actor,
25	  input: ListMembersInput,
26	): Promise<Page<MemberWithUser>> {
27	  assertOrgScope(actor, input.orgId);
28	  assertCan(actor, "member:read", {
29	    kind: "organization",
30	    orgId: input.orgId,
31	  });
32	  return memberRepo.listMembers(input);
33	}
34	
35	/**
36	 * Role changes carry two rules the permission matrix cannot express:
37	 * nobody may grant a role above their own, and the last owner may not be
38	 * demoted. Both are checked after `can()` has had its say.
39	 */
40	export async function updateMemberRole(
41	  actor: Actor,
42	  input: UpdateMemberRoleInput,
43	): Promise<Member> {
44	  assertOrgScope(actor, input.orgId);
45	
46	  const member = requireFound(
47	    await memberRepo.findMemberById(input.orgId, input.memberId),
48	    "Member",
49	    input.memberId,
50	  );
51	  assertCan(actor, "member:update_role", memberResource(member));
52	
53	  if (!hasRoleAtLeast(actor.role, input.role)) {
54	    throw new Error(
55	      `A ${actor.role} cannot grant the ${input.role} role`,
56	    );
57	  }
58	
59	  await assertLastOwnerRetained(input.orgId, input.memberId, input.role);
60	
61	  const updated = await memberRepo.updateMemberRole(
62	    input.orgId,
63	    input.memberId,
64	    input.role,
65	  );
66	
67	  await emit("member.role_changed", {
68	    ...actorEnvelope(actor),
69	    memberId: updated.id,
70	    from: member.role,
71	    to: updated.role,
72	  });
73	
74	  return updated;
75	}
